rows=[
 (1,'clinical_photograph','Close-up anterior neck photograph with black and red arrows.','A rounded prominent anterior neck contour fills the image above blue fabric. One black arrow enters from image left and points to the bulging contour; one red arrow enters from lower right and points to a faint curved/transverse line in the lower neck. Skin creases are visible superiorly. No panel letters, measurement scale or patient identifier is shown.',7,'A well-healed transverse surgical scar was noted in the lower neck (Figure 1).','clinical_photography',None,'The caption identifies enlargement and a prior operative scar on this patient’s neck; the case describes a predominantly right-lobe multinodular enlargement.', 'disease_course',[]),
 (2,'medical_imaging','Single grayscale neck ultrasound with two red arrows and one blue arrow.','One fan-shaped grayscale acquisition has a bright superficial layered band, heterogeneous gray tissue with scattered darker areas and a darker round/oval region inferiorly. Two red arrows from upper left and upper right point inward to gray tissue; one blue arrow from below points to the darker inferior region. Small white cross markers appear in the acquisition, without readable numeric measurements. LOGIQ S8 is printed at upper left. No panel labels or readable dimensional values are present.',35,'Ultrasound demonstrated enlargement of both thyroid lobes, with a markedly enlarged right lobe containing multiple nodules of varying size and showing retrosternal extension (Figure 2).','ultrasound','transverse plane','The caption identifies enlarged heterogeneous thyroid tissue and a hypo-echoic trachea displaced leftward by the enlarged right lobe; this is the case’s ultrasound assessment.', 'diagnostic_evidence',['No diagnostic graph or quantitative measurement is inferred from the ultrasound markers.']),
 (3,'medical_imaging','Single sagittal neck CT with red, blue and white arrows.','A sagittal section shows the head and cervical spine in profile, a dark upper airway and a broad heterogeneous gray mass-like region in the lower anterior neck. A red horizontal arrow points to its anterior border; a blue oblique arrow points into its inferior portion; a white arrow points to a bright round bony density lower/anteriorly. No calipers, numeric dimensions or panel letters are visible.',36,'Computed tomography (CT) of the neck showed diffuse thyroid enlargement with heterogeneous parenchyma (Figure 3).','ct','Sagittal non-contrast CT','The caption identifies markedly enlarged lower cervical thyroid, inferior retrosternal extension and a clavicular landmark. The case uses CT to establish extent for operative planning.', 'treatment_planning',[]),
 (4,'medical_imaging','Single coronal neck CT with paired green/white arrows and red/blue arrows.','A coronal section depicts a large heterogeneous gray lower-neck region, more bulky at image left, around an elongated dark airway shifted toward image right inferiorly. Two green arrows point inward from the sides to gray structures; two white arrows point to bright rounded bony densities near the lower lateral margins. One red arrow points to the lower dark airway and one blue arrow to the inferior image-left gray region. No numeric caliber measurement or panel letters are present.',36,'There was leftward tracheal deviation with mild narrowing, although the airway remained patent (Figure 4).','ct','Coronal CT image of the neck without contrast','The caption assigns the thyroid’s inferior extent, brachiocephalic vessel relationship, carotid landmarks and leftward tracheal deviation. Body CT describes mild narrowing with patent airway; caption says no significant airway compromise, and discussion says no compression. No exact reduction percentage is provided.', 'treatment_planning',['Body mild narrowing, caption no significant airway compromise and discussion no compression are preserved as distinct source wording.']),
 (5,'operative_photograph','Unlettered operative photograph of exposed lobulated tissue through a cervical field.','A large shiny dark-red lobulated tissue mass protrudes from an open operative field surrounded by blue drapes. Blood-stained gloved hands hold or retract tissue; metal instruments and clamps flank the exposed region. No arrows, panel letters, rulers or labels are visible. Appearance cannot independently establish nerve preservation, parathyroid function, blood loss or histologic diagnosis.',40,'The patient underwent a total thyroidectomy through a cervical approach (Figure 5).','clinical_photography',None,'The caption documents cervical thyroidectomy with exposed thyroid and retracted skin/subcutaneous tissues, linked to the patient’s performed total thyroidectomy.', 'procedure_documentation',[]),
 (6,'specimen_photograph','Gross lobulated specimen on a blue drape beside a yellow centimeter ruler.','A shiny dark-red lobulated specimen lies on blue fabric, with a larger elongated component at image right and a smaller lobulated component at image left linked by tissue. A yellow ruler lies along its right side, with centimeter label and readable numbers from 0 through 15; its placement does not align cleanly with specimen endpoints. A white packet edge appears at bottom. No scale-derived exact specimen dimensions or weight is inferred.',40,'Both thyroid lobes and the isthmus were removed (Figure 6).','clinical_photography',None,'The caption reports approximately 410 g specimen weight and right-lobe 14 × 8.5 cm, left-lobe 8.5 × 3.5 × 4 cm and isthmus 2 × 2 cm. These are author measurements, independently of the visible ruler.', 'procedure_documentation',['Visible ruler graduations are a physical scale, not a diagnostic chart; specimen orientation/endpoints prevent reliable independent exact dimension measurement.']),
 (7,'specimen_photograph','Gross lobulated specimen photograph with one black arrow.','A shiny dark-red lobulated specimen rests on light-blue drape, with a broad upper tissue mass and a smaller inferior lobulated component. One black arrow from image right points toward a narrow projection along the lower-right border of the upper mass. A partially clipped yellow object and thread appear above, and a clipped yellow ruler edge appears at bottom. No legible numerical dimension, panel letter or histology section is displayed.',46,'The entire specimen was submitted for microscopic evaluation in 51 tissue blocks (Figure 7).','clinical_photography',None,'The caption calls this total thyroid gland with pyramidal lobe and states that pathology confirmed benign multinodular goiter. The body’s operative term is paramedian lobe; pixels do not independently resolve the anatomical name or show microscopic malignancy exclusion.', 'procedure_documentation',['Caption pyramidal versus operative body paramedian naming is unresolved; the black-arrow target is visible but exact lobe identity is source-dependent.'])]
out=[]
for number,kind,general,detail,body_n,body_q,modality,sub,statement,role,extra_limits in rows:
 fid=f'FIG{number}';n=58+number;caption=S['figures'][number-1]['caption'];cq=B[f'b{n:05d}'];limits=['One unlettered whole-image scope; no invented panel letters.','Patient/specimen identity comes from explicit case figure linkage, not visual resemblance.','Author anatomical and diagnostic claims remain separately cited; no diagnosis or unprinted measurements inferred from pixels.']+extra_limits
 domains=[tag('endocrinology',n,caption,'thyroid')] if False else [tag('endocrinology',38,'giant recurrent retrosternal multinodular goiter','goiter',basis='article')]
